select id, category, price, cost, stock_qty, launch_date, tags, lag(price, 1, 0) over (partition by brand order by price, id) prev_price, sum(price) over (partition by supplier_id, category order by cost, id rows between unbounded preceding and current row) cumulative_price, ntile(10) over (partition by category, brand order by stock_qty desc, id) stock_qty_bucket, dense_rank() over (partition by supplier_id order by stock_qty desc nulls last) stock_qty_dense_rank, lead(stock_qty, 1) over (partition by supplier_id order by launch_date, id) next_stock_qty from products
